    float3 rd = normalize(float3(ndc.x * aspect / u_cam.x, ndc.y / u_cam.x, -1.0));
    float3 sc = float3(0.0, 0.0, -3.0);
    float scale = u_cam.y;
    float disp = 0.30 * INTENSITY;
    float3 twistAxis = normalize(float3(-0.68, 0.54, 0.49));
    float radius = scale;
    float h = 0.0; bool seen = false;
    // Two passes: the plain sphere's hit names a height, the sphere re-sized by it
    // is hit again — the displaced surface, near enough, without the mesh.
    for (int i = 0; i < 2; i++) {
        if (float(i) >= u_cam.z) { break; }
        float mid = dot(rd, sc);
        float disc = mid * mid - dot(sc, sc) + radius * radius;
        if (disc < 0.0) { break; }
        float3 obj = (rd * (mid - sqrt(disc)) - sc) / scale;
        float3 base = float3(dot(u_rot0.xyz, obj), dot(u_rot1.xyz, obj), dot(u_rot2.xyz, obj));
        float3 dir = normalize(base);
        dir = normalize(rotateAxis(base, twistAxis, -torsion(dir)));
        h = heightField(dir);
        seen = true;
        radius = scale * max(1.0 + h * disp, 0.72);
    }
