    if (seen) {
        col = gradientAt(spread(h * 0.5 + 0.5));
    } else {
        // Past the sphere: the same gradient along a fixed diagonal.
        float2 axis = normalize(float2(0.62 * aspect, 0.78));
        float2 centered = float2((uv.x - 0.5) * aspect, uv.y - 0.5);
        float extent = abs(axis.x) * aspect * 0.5 + abs(axis.y) * 0.5;
        col = gradientAt(dot(centered, axis) / max(extent * 2.0, 0.0001) + 0.5);
    }

    // Calm: flatten the field toward its own ground — the pools dim and the
    // corners lift, so a form screen keeps real colour under its glass rows while
    // losing the launcher's contrast. Motion is untouched (see the doc comment).
    col = mix(col, col * 0.60 + u_lift.rgb, calm);

    // Elliptical vignette: clear at r=0.25 → black·0.42 at r=1.15 (aspect-fit ellipse).
    // Halved under calm: a launcher's cards sit in the pooled centre, but a form
    // screen's rows run out toward the edges, where crushing to black just eats them.
    float2 e = (uv - 0.5) * 2.0;
    float vig = clamp((length(e) - 0.25) / 0.90, 0.0, 1.0)
              * mix(0.42, 0.21, calm) * u_scrim.a;
    col = mix(col, u_scrim.rgb, vig);

    // Vertical legibility scrim: black 0.38/0.06/0.08/0.40 at 0/0.32/0.68/1.
    float v = uv.y;
    float s = v < 0.32 ? mix(0.38, 0.06, v / 0.32)
            : v < 0.68 ? mix(0.06, 0.08, (v - 0.32) / 0.36)
            : mix(0.08, 0.40, (v - 0.68) / 0.32);
    col = mix(col, u_scrim.rgb, s * u_scrim.a);

    return half4(half3(col), 1.0);
}

